styles.css:
/* @mmianji-requires: idic.winter-snowman-list-header-named-v1 */
:root {
  --global-background-image: none;
  --global-theme-color: #181C24;
  --wf-canvas: #F5F6F9;
  --wf-canvas-soft: #FAFBFD;
  --wf-surface: #FFFFFF;
  --wf-surface-glass: rgba(255, 255, 255, 0.90);
  --wf-mist: #ECEFF4;
  --wf-mist-deep: #E2E6EE;
  --wf-ink: #181C24;
  --wf-ink-soft: #3A4252;
  --wf-muted: #7B8494;
  --wf-faint: #9DA5B4;
  --wf-accent: #5C7290;
  --wf-lamp: #B8A386;
  --wf-line: rgba(20, 26, 38, 0.065);
  --wf-line-strong: rgba(20, 26, 38, 0.12);
  --wf-shadow-card: 0 4px 18px -6px rgba(18, 25, 38, 0.08), 0 1px 3px rgba(18, 25, 38, 0.03);
  --wf-shadow-float: 0 10px 28px -10px rgba(18, 25, 38, 0.12), 0 2px 6px rgba(18, 25, 38, 0.04);
  --wf-hero-main: url("data:image/webp;base64,");
  --wf-hero-sub: url("data:image/webp;base64,");
  --wf-placeholder-img: url("data:image/png;base64,");
  --wf-font-sans: -apple-system, BlinkMacSystemFont, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "Segoe UI", sans-serif;
  --wf-font-serif: Georgia, "Times New Roman", "Noto Serif SC", "Songti SC", serif;
}

body,
.view,
input,
textarea,
button {
  font-family: var(--wf-font-sans);
}

#chat-list-view {
  background: linear-gradient(180deg, #FAFBFD 0%, #F5F6F9 100%) !important;
  background-image: linear-gradient(180deg, #FAFBFD 0%, #F5F6F9 100%) !important;
  color: #181C24 !important;
}

/* 24px 细线图标系统：高对比度、无渐变糊色 */
.wf-ico-wrap {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  pointer-events: none !important;
  flex: 0 0 auto !important;
}

svg.wf-ico {
  display: block !important;
  width: 22px !important;
  height: 22px !important;
  fill: none !important;
  stroke: none !important;
  overflow: visible !important;
}

svg.wf-ico .l {
  fill: none !important;
  stroke: currentColor !important;
  stroke-width: 1.65 !important;
  stroke-linecap: round !important;
  stroke-linejoin: round !important;
}

svg.wf-ico .d,
svg.wf-ico .a {
  fill: currentColor !important;
  stroke: none !important;
}

svg.wf-ico .r {
  fill: #A64444 !important;
  stroke: none !important;
}

svg.wf-ico .f {
  fill: none !important;
}

.wf-iconized > svg:not(.wf-ico),
.wf-iconized > i {
  display: none !important;
}

.wf-deco-branch,
.wf-deco-rule,
.wf-chat-frost-mark {
  display: none !important;
}

button.close-button.wf-iconized,
#create-post-button.wf-iconized,
#add-transaction-fab.wf-iconized,
#save-theme-preset-btn.wf-iconized,
#delete-theme-preset-btn.wf-iconized {
  font-size: 0 !important;
}

button.wf-iconized > .wf-ico-wrap {
  display: inline-flex !important;
}

:is(#chat-list-view, #chat-window-view, #group-chat-view, #app-nav, #side-menu, #moments-view, #contact-settings-view, #theme-settings-view) :where(button, input, textarea, [tabindex]):focus-visible {
  outline: 2px solid #5C7290;
  outline-offset: 2px;
}

/* 头像：纯白描边 + 轻柔投影 */
.avatar,
.chat-list-item .avatar,
.message-row .avatar {
  border-radius: 50% !important;
  border: 1.5px solid #FFFFFF !important;
  box-shadow: 0 2px 8px rgba(18, 25, 38, 0.09) !important;
}

.group-avatar-grid {
  border-radius: 14px !important;
  border: 1.5px solid #FFFFFF !important;
  background-color: #ECEFF4 !important;
  box-shadow: 0 2px 8px rgba(18, 25, 38, 0.08) !important;
}

/* 未读提示：雪花配小角标，数字仍来自实际未读数 */
.unread-badge {
  background-color: #181C24 !important;
  background-image: none !important;
  color: #FFFFFF !important;
  font-size: 10.5px !important;
  font-weight: 600 !important;
  border: 1.5px solid #FFFFFF !important;
  box-shadow: 0 2px 6px rgba(18, 25, 38, 0.22) !important;
}

/* 底栏：轻盈白玻璃悬浮坞，选中项改用柔雾底 + 寒墨字/线 */
#app-nav {
  left: 14px !important;
  right: 14px !important;
  width: auto !important;
  bottom: calc(10px + var(--idic-safe-bottom, env(safe-area-inset-bottom, 0px))) !important;
  height: 56px !important;
  padding: 5px 6px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  gap: 4px !important;
  border: 1px solid rgba(20, 26, 38, 0.065) !important;
  border-radius: 22px !important;
  background: rgba(255, 255, 255, 0.90) !important;
  background-image: none !important;
  backdrop-filter: blur(22px) saturate(1.15) !important;
  -webkit-backdrop-filter: blur(22px) saturate(1.15) !important;
  box-shadow: 0 10px 30px -10px rgba(18, 25, 38, 0.14), 0 1px 4px rgba(18, 25, 38, 0.04) !important;
  overflow: visible !important;
}

#app-nav.hidden {
  display: none !important;
}

#app-nav::before,
#app-nav::after,
#app-nav .wf-deco-rule-nav {
  display: none !important;
  content: none !important;
}

#app-nav .nav-button {
  position: relative !important;
  flex: 1 1 0 !important;
  height: 44px !important;
  margin: 0 !important;
  padding: 0 8px !important;
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 6px !important;
  border-radius: 16px !important;
  background: transparent !important;
  color: #9DA5B4 !important;
  font-size: 12px !important;
  font-weight: 500 !important;
  letter-spacing: 0.3px !important;
  transition: background-color 0.2s ease, color 0.2s ease !important;
}

#app-nav .nav-button i,
#app-nav .nav-button svg:not(.wf-ico) {
  display: none !important;
}

#app-nav .nav-button span:not(.wf-ico-wrap) {
  font-size: 12px !important;
  line-height: 1 !important;
}

#app-nav .wf-ico-nav,
#app-nav .nav-button.active .wf-ico-nav {
  width: 20px !important;
  height: 20px !important;
  border-radius: 0 !important;
  background: none !important;
  box-shadow: none !important;
  transform: none !important;
}

#app-nav .wf-ico-nav .wf-ico {
  width: 19px !important;
  height: 19px !important;
}

#app-nav .nav-button.active {
  background: rgba(24, 28, 36, 0.065) !important;
  color: #181C24 !important;
  font-weight: 600 !important;
}

#app-nav .nav-button.active .wf-ico .l {
  stroke: #181C24 !important;
  stroke-width: 1.85 !important;
}

#app-nav .nav-button.active .wf-ico .d,
#app-nav .nav-button.active .wf-ico .a {
  fill: #181C24 !important;
}

#app-nav .nav-button::after,
#app-nav .nav-button.active::after {
  content: none !important;
  display: none !important;
}

@media (max-width: 340px) {
  #app-nav {
    left: 8px !important;
    right: 8px !important;
  }
}


#chat-list-view .kiki-list-header {
  position: relative !important;
  z-index: 4 !important;
  border: 0 !important;
  border-radius: 0 !important;
  padding-bottom: 4px !important;
  background: linear-gradient(180deg, rgba(250, 251, 253, 0.96) 0%, rgba(246, 247, 250, 0.88) 76%, rgba(245, 246, 249, 0) 100%) !important;
  background-image: linear-gradient(180deg, rgba(250, 251, 253, 0.96) 0%, rgba(246, 247, 250, 0.88) 76%, rgba(245, 246, 249, 0) 100%) !important;
  box-shadow: none !important;
  backdrop-filter: blur(12px) !important;
  -webkit-backdrop-filter: blur(12px) !important;
  color: #181C24 !important;
}

#chat-list-view .kiki-list-header::before,
#chat-list-view .kiki-list-header::after {
  content: none !important;
  display: none !important;
}

#chat-list-view .kiki-list-header .main-header {
  position: relative !important;
  z-index: 1 !important;
  padding: calc(var(--idic-safe-top, 0px) + 10px) 16px 8px !important;
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
}

#chat-list-view #main-header-user-info .avatar {
  width: 40px !important;
  height: 40px !important;
  border-radius: 50% !important;
  border: 2px solid #FFFFFF !important;
  outline: none !important;
  box-shadow: 0 3px 10px -2px rgba(18, 25, 38, 0.14) !important;
}

#chat-list-view #main-header-username {
  color: #181C24 !important;
  font-size: 16px !important;
  font-weight: 650 !important;
  letter-spacing: 0.2px !important;
}

#chat-list-view #main-header-user-info .user-status {
  color: #7B8494 !important;
  font-size: 11px !important;
}

#chat-list-view #main-header-user-info .status-dot,
#chat-window-view .online-indicator {
  width: 7px !important;
  height: 7px !important;
  background: #5C7290 !important;
  background-image: none !important;
  box-shadow: 0 0 0 2px rgba(92, 114, 144, 0.14) !important;
}

.header-button,
#back-to-list-button,
#chat-settings-button,
#add-contact-button {
  width: 36px !important;
  height: 36px !important;
  min-width: 36px !important;
  padding: 0 !important;
  border-radius: 50% !important;
  border: 1px solid rgba(20, 26, 38, 0.065) !important;
  background: #FFFFFF !important;
  background-image: none !important;
  box-shadow: 0 4px 18px -6px rgba(18, 25, 38, 0.08), 0 1px 3px rgba(18, 25, 38, 0.03) !important;
  color: #181C24 !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  position: relative !important;
  top: auto !important;
  right: auto !important;
  transform: none !important;
  z-index: 1 !important;
  transition: transform 0.16s ease, box-shadow 0.16s ease !important;
}

.header-button.wf-iconized,
#add-contact-button.wf-iconized {
  font-size: 0 !important;
}

.header-button:active,
#back-to-list-button:active,
#chat-settings-button:active,
#add-contact-button:active {
  transform: scale(0.93) !important;
}

.header-button .wf-ico,
#back-to-list-button .wf-ico,
#chat-settings-button .wf-ico,
#add-contact-button .wf-ico {
  width: 18px !important;
  height: 18px !important;
}

.header-button svg:not(.wf-ico) {
  width: 17px !important;
  height: 17px !important;
  stroke: #181C24 !important;
}

.header-button img {
  width: 18px !important;
  height: 18px !important;
  object-fit: contain !important;
}

#chat-list-view .search-bar-container {
  padding: 0 16px 6px !important;
  margin: 0 !important;
  background: transparent !important;
}

#chat-list-view .search-bar-container .search-bar,
#chat-list-view .search-bar {
  margin: 0 !important;
  height: 40px !important;
  min-height: 40px !important;
  padding: 0 5px 0 4px !important;
  border-radius: 999px !important;
  border: 1px solid rgba(20, 26, 38, 0.065) !important;
  background: #FFFFFF !important;
  background-image: none !important;
  box-shadow: 0 4px 18px -6px rgba(18, 25, 38, 0.08), 0 1px 3px rgba(18, 25, 38, 0.03) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

#chat-list-view .search-bar > svg.search-icon {
  display: none !important;
}

#chat-list-view .search-bar > .wf-search-icon {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  flex: none !important;
  width: 20px !important;
  height: 20px !important;
  margin: 0 6px 0 11px !important;
  color: #7B8494 !important;
  pointer-events: none !important;
}

#chat-list-view .search-bar > .wf-search-icon .wf-ico {
  width: 16px !important;
  height: 16px !important;
}

#chat-list-view .search-bar input,
#chat-list-view #chat-list-search-input {
  background: transparent !important;
  background-image: none !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 6px !important;
  height: 100% !important;
  text-align: left !important;
  color: #181C24 !important;
  -webkit-text-fill-color: #181C24 !important;
  font-size: 13px !important;
  font-weight: 450 !important;
  text-shadow: none !important;
}

#chat-list-view .search-bar input::placeholder,
#chat-list-view #chat-list-search-input::placeholder {
  color: #9DA5B4 !important;
  -webkit-text-fill-color: #9DA5B4 !important;
  opacity: 1 !important;
}

#chat-list-view #toggle-filters-btn {
  width: 30px !important;
  height: 30px !important;
  min-width: 30px !important;
  border-radius: 50% !important;
  border: 0 !important;
  background: #ECEFF4 !important;
  color: #181C24 !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
}

#chat-list-view #toggle-filters-btn .wf-ico {
  width: 15px !important;
  height: 15px !important;
}



#chat-list-view:not(.hidden) {
  position: relative !important;
  display: flex !important;
  flex-direction: column !important;
  overflow: hidden !important;
}

#chat-list-view.hidden {
  display: none !important;
}

#chat-list-view .wf-list-shell-top {
  position: relative !important;
  z-index: 3 !important;
  flex: 0 0 auto !important;
  margin: 0 14px !important;
  padding: 2px 0 0 !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  color: #181C24 !important;
  user-select: none !important;
}

#chat-list-view .wf-sheet-tab,
#chat-list-view .wf-masthead-weather,
#chat-list-view .wf-hero-stamp,
#chat-list-view .wf-hero-sub-tag,
#chat-list-view .wf-photo-frost,
#chat-list-view .wf-spine,
#chat-list-view .wf-hero-caption {
  display: none !important;
}

#chat-list-view .wf-masthead {
  display: flex !important;
  align-items: center !important;
  gap: 8px !important;
  height: 22px !important;
  padding: 0 2px 3px !important;
}

#chat-list-view .wf-masthead-issue {
  font-family: var(--wf-font-serif) !important;
  font-size: 10px !important;
  font-weight: 500 !important;
  letter-spacing: 1.5px !important;
  color: #7B8494 !important;
  background: none !important;
  -webkit-text-fill-color: #7B8494 !important;
  white-space: nowrap !important;
}

#chat-list-view .wf-masthead-date {
  font-family: var(--wf-font-serif) !important;
  color: #181C24 !important;
  -webkit-text-fill-color: #181C24 !important;
}

#chat-list-view .wf-masthead-rule {
  flex: 1 1 auto !important;
  height: 1px !important;
  background: linear-gradient(90deg, rgba(20, 26, 38, 0.12), rgba(20, 26, 38, 0.02)) !important;
}

#chat-list-view .wf-masthead-whisper {
  display: inline-flex !important;
  align-items: center !important;
  gap: 4px !important;
  padding: 1px 7px !important;
  border-radius: 999px !important;
  background: rgba(255, 255, 255, 0.92) !important;
  border: 1px solid rgba(20, 26, 38, 0.065) !important;
  color: #5C7290 !important;
  font-size: 9.5px !important;
  font-weight: 500 !important;
  letter-spacing: 0.2px !important;
  white-space: nowrap !important;
  max-width: 58% !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  opacity: 0 !important;
  transform: translateY(-2px) !important;
  transition: opacity 0.25s ease, transform 0.25s ease !important;
  pointer-events: none !important;
}

#chat-list-view .wf-masthead-whisper.is-visible {
  display: inline-flex !important;
  opacity: 1 !important;
  transform: translateY(0) !important;
}

#chat-list-view .wf-masthead-whisper:not(.is-visible) {
  display: none !important;
}

#chat-list-view .wf-music-snow-btn {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  width: 22px !important;
  height: 22px !important;
  padding: 0 !important;
  border: 0 !important;
  border-radius: 50% !important;
  background: transparent !important;
  color: #7B8494 !important;
  cursor: pointer !important;
  transition: transform 0.45s cubic-bezier(0.22, 1, 0.36, 1), color 0.2s ease, background-color 0.2s ease !important;
}

#chat-list-view .wf-music-snow-btn:hover,
#chat-list-view .wf-music-snow-btn:active {
  color: #181C24 !important;
  background: rgba(24, 28, 36, 0.05) !important;
}

#chat-list-view .wf-music-snow-btn.is-spun {
  transform: rotate(180deg) !important;
}

#chat-list-view .wf-music-eq {
  display: none !important;
  align-items: flex-end !important;
  gap: 2px !important;
  height: 9px !important;
  margin-left: 5px !important;
  margin-right: auto !important;
}

#chat-list-view .wf-music-player.is-animated .wf-music-eq {
  display: inline-flex !important;
}

#chat-list-view .wf-music-eq i {
  display: block !important;
  width: 1.5px !important;
  height: 4px !important;
  border-radius: 1px !important;
  background: #B8A386 !important;
  animation: wfEqPulse 0.9s ease-in-out infinite alternate !important;
}

#chat-list-view .wf-music-eq i:nth-child(2) {
  height: 8px !important;
  animation-delay: 0.2s !important;
}

#chat-list-view .wf-music-eq i:nth-child(3) {
  height: 5px !important;
  animation-delay: 0.4s !important;
}

@keyframes wfEqPulse {
  from { transform: scaleY(0.45); opacity: 0.65; }
  to { transform: scaleY(1.1); opacity: 1; }
}

#chat-list-view .wf-hero-sub-card {
  cursor: pointer !important;
  transition: transform 0.35s cubic-bezier(0.22, 1, 0.36, 1) !important;
}

#chat-list-view .wf-hero-sub-card.is-tilted {
  transform: rotate(2deg) scale(1.03) !important;
}

#chat-list-view .wf-empty-snowman {
  width: 38px !important;
  height: 40px !important;
  flex: none !important;
}

#chat-list-view .wf-hero-wrap {
  position: relative !important;
  display: block !important;
}

#chat-list-view .wf-hero-snowman-sticker {
  display: none !important;
  position: absolute !important;
  left: 28.5% !important;
  top: 126px !important;
  width: 46px !important;
  height: 50px !important;
  transform: rotate(-4deg) !important;
  pointer-events: none !important;
  user-select: none !important;
  z-index: 6 !important;
}

#chat-list-view .wf-hero-grid {
  position: relative !important;
  display: block !important;
  width: 100% !important;
  height: 182px !important;
  padding: 0 !important;
  border-radius: 18px !important;
  border: 1px solid rgba(20, 26, 38, 0.065) !important;
  background: #FFFFFF !important;
  box-shadow: 0 10px 28px -10px rgba(18, 25, 38, 0.12), 0 2px 6px rgba(18, 25, 38, 0.04) !important;
  overflow: hidden !important;
}

#chat-list-view .wf-hero-grid::before,
#chat-list-view .wf-hero-grid::after {
  content: none !important;
  display: none !important;
}

#chat-list-view .wf-hero-main-card {
  position: absolute !important;
  inset: 0 !important;
  display: block !important;
  width: auto !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  border-radius: 18px !important;
  background: #FFFFFF !important;
  box-shadow: none !important;
  overflow: hidden !important;
}

#chat-list-view .wf-hero-main-card .wf-hero-inner {
  position: relative !important;
  width: 100% !important;
  height: 100% !important;
  border-radius: 18px !important;
  overflow: hidden !important;
  background: #FFFFFF !important;
}

#chat-list-view .wf-hero-photo,
#chat-list-view .wf-hero-sub-photo {
  width: 100% !important;
  height: 100% !important;
  background-color: #ECEFF4 !important;
  background-size: cover !important;
  filter: saturate(0.72) brightness(1.03) contrast(1.02) !important;
}

#chat-list-view .wf-hero-photo {
  background-image: var(--wf-hero-main) !important;
  background-position: 70% center !important;
}

#chat-list-view .wf-hero-sub-photo {
  background-image: var(--wf-hero-sub) !important;
  background-position: center !important;
}

#chat-list-view .wf-hero-main-card .wf-hero-gloss {
  position: absolute !important;
  inset: 0 !important;
  pointer-events: none !important;
  background: linear-gradient(90deg, rgba(255, 255, 255, 0) 14%, rgba(255, 255, 255, 0.14) 32%, rgba(255, 255, 255, 0.72) 52%, rgba(255, 255, 255, 0.97) 72%, #FFFFFF 100%) !important;
}

#chat-list-view .wf-hero-side {
  display: contents !important;
}

#chat-list-view .wf-hero-sub-card {
  position: absolute !important;
  left: 5.5% !important;
  right: auto !important;
  top: auto !important;
  bottom: 14px !important;
  width: 26% !important;
  height: 64px !important;
  padding: 0 !important;
  border: 0 !important;
  border-radius: 11px !important;
  background: transparent !important;
  box-shadow: 0 6px 16px -4px rgba(18, 25, 38, 0.18) !important;
  overflow: hidden !important;
  transform: rotate(-2.2deg) !important;
  z-index: 3 !important;
}

#chat-list-view .wf-hero-sub-card .wf-hero-inner {
  width: 100% !important;
  height: 100% !important;
  border-radius: 11px !important;
  overflow: hidden !important;
}

#chat-list-view .wf-hero-sub-card .wf-hero-gloss {
  display: none !important;
}

#chat-list-view .wf-music-player {
  position: absolute !important;
  z-index: 5 !important;
  top: 12px !important;
  right: 13px !important;
  bottom: 10px !important;
