/* 红包详情弹窗：极简纯白凭证，无水印、无伪英文头、无重投影 */
#red-packet-modal {
  background: rgba(0, 0, 0, 0.38) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

#red-packet-modal .red-packet-content {
  width: 100% !important;
  max-width: 420px !important;
  height: 100% !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  justify-content: center !important;
  padding: 0 !important;
  background: none !important;
  background-image: none !important;
  border: 0 !important;
  box-shadow: none !important;
}

#red-packet-modal .close-button,
#red-packet-modal #close-rp-modal-button {
  position: absolute !important;
  top: calc(20px + var(--idic-safe-top, 0px)) !important;
  right: 16px !important;
  width: 34px !important;
  height: 34px !important;
  border: 0 !important;
  background: transparent !important;
  color: #FFFFFF !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  box-shadow: none !important;
}

#red-packet-modal .rp-header {
  flex: 0 0 auto !important;
  width: min(280px, calc(100vw - 48px)) !important;
  box-sizing: border-box !important;
  padding: 26px 24px 20px !important;
  background: #FFFFFF !important;
  background-image: none !important;
  border: 1px solid #E6E6EA !important;
  border-bottom: 0 !important;
  border-radius: 12px 12px 0 0 !important;
  text-align: center !important;
  color: #18181A !important;
  box-shadow: none !important;
}

#red-packet-modal .rp-header::before {
  content: none !important;
  display: none !important;
}

#red-packet-modal #rp-sender-avatar {
  display: block !important;
  width: 40px !important;
  height: 40px !important;
  margin: 0 auto 10px !important;
  border: 1px solid #E6E6EA !important;
  border-radius: 50% !important;
  box-shadow: none !important;
}

#red-packet-modal #rp-sender-name {
  margin: 0 0 4px !important;
  color: #787880 !important;
  font-size: 11.5px !important;
  font-weight: 400 !important;
}

#red-packet-modal #rp-blessing {
  margin: 0 0 18px !important;
  color: #18181A !important;
  font-size: 15px !important;
  font-weight: 500 !important;
}

#red-packet-modal .rp-amount-line {
  margin: 0 !important;
  padding: 16px 0 4px !important;
  border-top: 1px solid #E6E6EA !important;
  border-bottom: 0 !important;
  color: #18181A !important;
  font-size: 32px !important;
  font-weight: 500 !important;
  font-variant-numeric: tabular-nums !important;
  letter-spacing: -0.02em !important;
}

#red-packet-modal .rp-currency {
  font-size: 16px !important;
  font-weight: 400 !important;
  color: #787880 !important;
  margin-right: 3px !important;
